/// Merge the routes of `other`'s fallback router into `self`'s.
///
/// `self_default_fallback` and `other_default_fallback` indicate whether the
/// routers' top-level fallbacks are the default `NotFound` ones. Endpoints at
/// the top-level fallback paths are only replaced if `self`'s is the default
/// and `other`'s is not, such that custom fallbacks always win over defaults.
/// Nested fallback endpoints are added unless a custom fallback already
/// exists at that path.
fn merge_fallback_router(
    &mut self,
    other_fallback_router: PathRouter<S, true>,
    self_default_fallback: bool,
    other_default_fallback: bool,
) {
    let other_routes = other_fallback_router.routes;
    let other_node = other_fallback_router.node;

    let top_level_fallback_paths = [
        "/".to_owned(),
        format!("/*{FALLBACK_PARAM}"),
    ];

    for (id, endpoint) in other_routes {
        let path = other_node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue");

        let path = &**path;

        let is_top_level_fallback_path = top_level_fallback_paths.contains(&path.to_owned());

        let self_endpoint_is_default =
            self_default_fallback && is_top_level_fallback_path;
        let other_endpoint_is_default =
            other_default_fallback && is_top_level_fallback_path;

        match self.fallback_router.node.path_to_route_id.get(path) {
            Some(route_id) => {
                if self_endpoint_is_default && !other_endpoint_is_default {
                    self.fallback_router.routes.insert(*route_id, endpoint);
                }
            }
            None => panic_on_err!(self.fallback_router.route_endpoint(path, endpoint)),
        }
    }
}

